// 1. SPATIAL LOCALITY (C/C++ arrays are row-major)
// Efficiently utilizes cache lines by reading adjacent memory.
int matrix[100][100];

// Optimal Access (Row-major: i then j)
for (int i = 0; i < 100; ++i) {
    for (int j = 0; j < 100; ++j) {
        matrix[i][j] = 0; // Sequential memory load
    }
}

